// Builds the GitHub Pages site into docs/_site.
//
// The site is assembled from three sources, none of which is duplicated here:
//
//   docs/site/**.md                     hand-written guides
//   server/openapi/**/service.yaml      OpenAPI specs, generated by `make gen`
//   .agents/skills/hub-api/references/  the API reference, generated by `make gen`
//
// Everything the build needs is vendored from node_modules, so the published
// pages load no third-party scripts at runtime.

import { cpSync, mkdirSync, readFileSync, readdirSync, rmSync, statSync, writeFileSync } from 'node:fs';
import { dirname, join, relative } from 'node:path';
import { fileURLToPath } from 'node:url';

import hljs from 'highlight.js';
import { Marked } from 'marked';
import { markedHighlight } from 'marked-highlight';
import { parse as parseYaml, stringify as stringifyYaml } from 'yaml';

const DOCS = dirname(fileURLToPath(import.meta.url));
const ROOT = join(DOCS, '..');
const SRC = join(DOCS, 'site');
const OUT = join(DOCS, '_site');
const MODULES = join(DOCS, 'node_modules');

const REPO = 'https://github.com/linzhengen/hub';

// The generated API reference lives with the agent skill; the site renders the
// same file rather than keeping a second copy in step by hand.
const API_REFERENCE = join(ROOT, '.agents/skills/hub-api/references/api-reference.md');

const LANGS = [
  { code: 'en', htmlLang: 'en', label: 'English', dir: '' },
  { code: 'ja', htmlLang: 'ja', label: '日本語', dir: 'ja' },
];

// Every href is relative to the site root; the page template rewrites them for
// the directory the page ends up in.
const NAV = {
  en: [
    { href: 'index.html', title: 'Overview', source: 'index.md' },
    { href: 'getting-started.html', title: 'Getting started', source: 'getting-started.md' },
    { href: 'cli.html', title: 'CLI', source: 'cli.md' },
    { href: 'api.html', title: 'API explorer' },
    { href: 'api-reference.html', title: 'API reference' },
  ],
  ja: [
    { href: 'ja/index.html', title: '概要', source: 'ja/index.md' },
    { href: 'ja/getting-started.html', title: 'はじめかた', source: 'ja/getting-started.md' },
    { href: 'ja/cli.html', title: 'CLI', source: 'ja/cli.md' },
    { href: 'api.html', title: 'API エクスプローラー' },
    { href: 'api-reference.html', title: 'API リファレンス' },
  ],
};

const escapeHtml = (s) =>
  s.replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');

// slug builds a heading id. It is given the heading's plain text, never its
// rendered HTML, so there is no markup to strip here.
const slug = (s) =>
  s
    .toLowerCase()
    .replace(/[^\p{L}\p{N}\s-]/gu, '')
    .trim()
    .replace(/\s+/g, '-');

function markdown() {
  const marked = new Marked(
    markedHighlight({
      emptyLangClass: 'hljs',
      langPrefix: 'hljs language-',
      highlight(code, lang) {
        // Mermaid blocks are drawn in the browser, so they are only escaped
        // here; the renderer below turns them into a <pre class="mermaid">.
        if (lang === 'mermaid') return escapeHtml(code);
        const language = hljs.getLanguage(lang) ? lang : 'plaintext';
        return hljs.highlight(code, { language }).value;
      },
    }),
  );

  const seen = new Map();
  marked.use({
    renderer: {
      code({ text, lang }) {
        if (lang === 'mermaid') return `<pre class="mermaid">${text}</pre>\n`;
        const cls = lang ? ` language-${escapeHtml(lang)}` : '';
        return `<pre><code class="hljs${cls}">${text}</code></pre>\n`;
      },
      heading({ tokens, depth }) {
        const text = this.parser.parseInline(tokens);
        // textRenderer yields the heading without any markup, which is what the
        // id is derived from.
        const base = slug(this.parser.parseInline(tokens, this.parser.textRenderer)) || `section-${depth}`;
        const count = (seen.get(base) ?? 0) + 1;
        seen.set(base, count);
        const id = count === 1 ? base : `${base}-${count}`;
        return `<h${depth} id="${id}"><a class="anchor" href="#${id}" aria-hidden="true">#</a>${text}</h${depth}>\n`;
      },
    },
  });
  return { render: (src) => (seen.clear(), marked.parse(src)) };
}

function pageShell({ lang, title, nav, activeHref, depth, body, head = '', scripts = '' }) {
  const base = depth === 0 ? '.' : '../'.repeat(depth).replace(/\/$/, '');
  const href = (target) => `${base}/${target}`;
  const navHtml = nav
    .map(
      (item) =>
        `<li><a href="${href(item.href)}"${item.href === activeHref ? ' aria-current="page"' : ''}>${escapeHtml(item.title)}</a></li>`,
    )
    .join('\n          ');
  const langHtml = LANGS.map((l) => {
    const target = l.dir ? `${l.dir}/index.html` : 'index.html';
    const current = l.code === lang;
    return `<a class="lang${current ? ' is-current' : ''}" href="${href(target)}"${current ? ' aria-current="true"' : ''}>${l.label}</a>`;
  }).join('');

  return `<!doctype html>
<html lang="${lang}">
  <head>
    <meta charset="utf-8" />
    <meta name="viewport" content="width=device-width, initial-scale=1" />
    <title>${escapeHtml(title)} · hub docs</title>
    <meta name="description" content="Documentation for hub — identity and access management with a Go API, a React UI, Keycloak and a generated CLI." />
    <link rel="icon" href="${href('assets/favicon.svg')}" type="image/svg+xml" />
    <link rel="stylesheet" href="${href('assets/styles.css')}" />
${head}  </head>
  <body>
    <header class="topbar">
      <a class="brand" href="${href(lang === 'en' ? 'index.html' : 'ja/index.html')}">
        <span class="brand-mark">hub</span>
        <span class="brand-sub">docs</span>
      </a>
      <div class="topbar-right">
        <div class="langs">${langHtml}</div>
        <a class="ghlink" href="${REPO}">GitHub</a>
      </div>
    </header>
    <div class="layout">
      <nav class="sidebar" aria-label="Documentation">
        <ul>
          ${navHtml}
        </ul>
      </nav>
      <main class="content">
${body}
      </main>
    </div>
${scripts}  </body>
</html>
`;
}

function copyVendor() {
  const vendor = join(OUT, 'vendor');
  mkdirSync(join(vendor, 'swagger-ui'), { recursive: true });
  for (const file of ['swagger-ui.css', 'swagger-ui-bundle.js', 'swagger-ui-standalone-preset.js']) {
    cpSync(join(MODULES, 'swagger-ui-dist', file), join(vendor, 'swagger-ui', file));
  }
  cpSync(join(MODULES, 'mermaid/dist/mermaid.min.js'), join(vendor, 'mermaid.min.js'));
}

function writeStyles() {
  const light = readFileSync(join(MODULES, 'highlight.js/styles/github.css'), 'utf8');
  const dark = readFileSync(join(MODULES, 'highlight.js/styles/github-dark.css'), 'utf8');
  const own = readFileSync(join(SRC, 'assets/styles.css'), 'utf8');
  const css = [own, light, `@media (prefers-color-scheme: dark) {\n${dark}\n}`].join('\n\n');
  mkdirSync(join(OUT, 'assets'), { recursive: true });
  writeFileSync(join(OUT, 'assets/styles.css'), css);
}

// collectSpecs finds the OpenAPI documents `make gen` writes and derives a
// label for each from its proto package, so a new service shows up in the
// explorer without this file being touched.
function collectSpecs() {
  const root = join(ROOT, 'server/openapi');
  const specs = [];
  const walk = (dir) => {
    for (const entry of readdirSync(dir, { withFileTypes: true }).sort((a, b) => a.name.localeCompare(b.name))) {
      const path = join(dir, entry.name);
      if (entry.isDirectory()) walk(path);
      else if (entry.name === 'service.yaml') {
        const pkg = relative(root, dirname(path)).split('/');
        const service = pkg[pkg.length - 2].replace(/^./, (c) => c.toUpperCase());
        specs.push({
          pkg: pkg.join('.'),
          name: `${service} · ${pkg.join('.')}`,
          title: `${service} API`,
          version: pkg[pkg.length - 1],
          from: path,
          url: `openapi/${pkg.join('/')}/service.yaml`,
        });
      }
    }
  };
  walk(root);
  return specs;
}

function build() {
  rmSync(OUT, { recursive: true, force: true });
  mkdirSync(OUT, { recursive: true });

  const md = markdown();
  const pages = [];

  for (const lang of LANGS) {
    for (const item of NAV[lang.code]) {
      if (!item.source) continue;
      const source = readFileSync(join(SRC, item.source), 'utf8');
      pages.push({ lang: lang.code, htmlLang: lang.htmlLang, href: item.href, title: item.title, source });
    }
  }

  // The API reference is generated by `hub api docs`; the site only re-renders it.
  pages.push({
    lang: 'en',
    htmlLang: 'en',
    href: 'api-reference.html',
    title: 'API reference',
    source: readFileSync(API_REFERENCE, 'utf8'),
  });

  for (const page of pages) {
    const bodyHtml = md.render(page.source);
    const depth = page.href.split('/').length - 1;
    const html = pageShell({
      lang: page.htmlLang,
      title: page.title,
      nav: NAV[page.lang],
      activeHref: page.href,
      depth,
      body: `<div class="prose">\n${bodyHtml}</div>`,
      scripts: bodyHtml.includes('class="mermaid"')
        ? `    <script src="${depth === 0 ? '.' : '..'}/vendor/mermaid.min.js"></script>
    <script>
      mermaid.initialize({
        startOnLoad: true,
        theme: window.matchMedia('(prefers-color-scheme: dark)').matches ? 'dark' : 'default',
      });
    </script>
`
        : '',
    });
    const target = join(OUT, page.href);
    mkdirSync(dirname(target), { recursive: true });
    writeFileSync(target, html);
  }

  // The OpenAPI documents come straight from `make gen`. Only the `info` block
  // is rewritten: protoc-gen-openapiv2 titles each document after its .proto
  // file and leaves the version unset, which reads as noise in the explorer.
  // Paths, schemas and parameters are published exactly as generated.
  const specs = collectSpecs();
  for (const spec of specs) {
    const doc = parseYaml(readFileSync(spec.from, 'utf8'));
    doc.info = { ...doc.info, title: spec.title, version: spec.version };
    const target = join(OUT, spec.url);
    mkdirSync(dirname(target), { recursive: true });
    writeFileSync(target, stringifyYaml(doc));
  }

  const swaggerBody = readFileSync(join(SRC, 'partials/swagger.html'), 'utf8').replace(
    '{{SPECS}}',
    JSON.stringify(specs.map(({ name, url }) => ({ name, url }))),
  );
  writeFileSync(
    join(OUT, 'api.html'),
    pageShell({
      lang: 'en',
      title: 'API explorer',
      nav: NAV.en,
      activeHref: 'api.html',
      depth: 0,
      body: swaggerBody,
      head: '    <link rel="stylesheet" href="./vendor/swagger-ui/swagger-ui.css" />\n',
      scripts: `    <script src="./vendor/swagger-ui/swagger-ui-bundle.js"></script>
    <script src="./vendor/swagger-ui/swagger-ui-standalone-preset.js"></script>
    <script src="./assets/api-explorer.js"></script>
`,
    }),
  );

  cpSync(join(SRC, 'assets'), join(OUT, 'assets'), { recursive: true });
  writeStyles();
  copyVendor();
  cpSync(join(DOCS, 'screenshots'), join(OUT, 'screenshots'), { recursive: true });
  writeFileSync(join(OUT, '.nojekyll'), '');

  const files = [];
  const measure = (dir) => {
    for (const entry of readdirSync(dir, { withFileTypes: true })) {
      const path = join(dir, entry.name);
      if (entry.isDirectory()) measure(path);
      else files.push(statSync(path).size);
    }
  };
  measure(OUT);
  const bytes = files.reduce((a, b) => a + b, 0);
  console.log(
    `built ${pages.length + 1} pages and ${specs.length} OpenAPI specs into docs/_site ` +
      `(${files.length} files, ${(bytes / 1024 / 1024).toFixed(1)} MB)`,
  );
}

build();
